<?php
declare(strict_types=1);

final class MothershipService
{
    public function __construct(private PDO $pdo) {}
    private function setting(string $key,int $default=0):int{$s=$this->pdo->prepare('SELECT setting_value FROM game_settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:max(0,(int)$v);}
    private function event(int $playerId,int $shipId,string $type,array $payload):void{$s=$this->pdo->prepare('INSERT INTO game_events(player_id,event_type,entity_type,entity_id,payload) VALUES(?,?,?,?,?)');$s->execute([$playerId,$type,'mothership',$shipId,json_encode($payload,JSON_THROW_ON_ERROR)]);}

    public function snapshot(int $playerId):array
    {
        if($playerId<1)throw new InvalidArgumentException('Invalid mothership request.');$s=$this->pdo->prepare('SELECT * FROM motherships WHERE player_id=?');$s->execute([$playerId]);$ship=$s->fetch(PDO::FETCH_ASSOC);if(!$ship)return ['state'=>'locked','mothership'=>null,'modules'=>[],'queue'=>[],'capacity'=>0,'formula'=>'mothership capacity = hull tier + hangar modules + technology modifier','states'=>['ready','locked','insufficient-resource','success','error']];$m=$this->pdo->prepare('SELECT module_key,level,durability FROM mothership_modules WHERE mothership_id=? ORDER BY module_key');$m->execute([(int)$ship['id']]);$modules=$m->fetchAll(PDO::FETCH_ASSOC);$q=$this->pdo->prepare("SELECT id,module_key,level_before,level_after,starts_at,completes_at,status FROM mothership_upgrade_queue WHERE player_id=? AND status IN ('queued','processing') ORDER BY completes_at");$q->execute([$playerId]);$queue=$q->fetchAll(PDO::FETCH_ASSOC);$t=$this->pdo->prepare("SELECT COALESCE(MAX(level),0) FROM player_technologies WHERE player_id=? AND (technology_key='mothership' OR technology_key='command' OR technology_name LIKE '%Mothership%')");$t->execute([$playerId]);$techLevel=(int)$t->fetchColumn();$techModifier=1+($techLevel*0.05);$capacity=(int)$ship['hull_level']+(int)$ship['fleet_hangars']+$techModifier;return ['state'=>'ready','mothership'=>['id'=>(int)$ship['id'],'name'=>$ship['name'],'hull_level'=>(int)$ship['hull_level'],'volley_bays'=>(int)$ship['volley_bays'],'shield_bays'=>(int)$ship['shield_bays'],'fleet_hangars'=>(int)$ship['fleet_hangars'],'weapons_power'=>(int)$ship['weapons_power'],'shields_power'=>(int)$ship['shields_power'],'exploration_level'=>(int)$ship['exploration_level'],'hull_integrity'=>min(100,(int)$ship['hull_level']*10),'hangar_capacity'=>(int)$ship['fleet_hangars']*100,'shield_strength'=>(int)$ship['shields_power']+(int)$ship['shield_bays']*100,'technology_level'=>$techLevel,'technology_modifier'=>round($techModifier,3)],'modules'=>$modules,'queue'=>$queue,'capacity'=>$capacity,'formula'=>'mothership capacity = hull tier + hangar modules + technology modifier','states'=>['ready','locked','insufficient-resource','success','error']];
    }

    public function upgrade(int $playerId,string $module):array
    {
        $allowed=['hull_level','volley_bays','shield_bays','fleet_hangars','weapons_power','shields_power','exploration_level'];if($playerId<1||!in_array($module,$allowed,true))throw new InvalidArgumentException('Invalid mothership module.');$this->pdo->beginTransaction();try{$cooldown=$this->setting('mothership_upgrade_cooldown_seconds');$c=$this->pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='mothership_upgrade' FOR UPDATE");$c->execute([$playerId]);$available=$c->fetchColumn();if($available!==false&&new DateTimeImmutable((string)$available)>new DateTimeImmutable('now'))throw new RuntimeException('Mothership upgrade is on cooldown.');$s=$this->pdo->prepare('SELECT * FROM motherships WHERE player_id=? FOR UPDATE');$s->execute([$playerId]);$ship=$s->fetch(PDO::FETCH_ASSOC);if(!$ship)throw new RuntimeException('Mothership not found.');$q=$this->pdo->prepare("SELECT COUNT(*) FROM mothership_upgrade_queue WHERE player_id=? AND status IN ('queued','processing') FOR UPDATE");$q->execute([$playerId]);if((int)$q->fetchColumn()>=3)throw new RuntimeException('Mothership upgrade queue is full.');$before=(int)$ship[$module];$max=$module==='hull_level'?21:50;if($before>=$max)throw new RuntimeException('Mothership module level cap reached.');$required=$module==='fleet_hangars'?max(1,$before+1):1;if($module!=='hull_level'&&$before>0&&(int)$ship['hull_level']<$required)throw new RuntimeException('Mothership hull prerequisite not met.');$cost=25000+($before*10000);$r=$this->pdo->prepare('SELECT naquadah FROM player_resources WHERE player_id=? FOR UPDATE');$r->execute([$playerId]);if((int)$r->fetchColumn()<$cost)throw new RuntimeException('Not enough Naquadah.');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$this->pdo->prepare("UPDATE motherships SET {$module}={$module}+1 WHERE player_id=?")->execute([$playerId]);$seconds=600+($before*60);$start=(new DateTimeImmutable('now'))->format('Y-m-d H:i:s');$complete=(new DateTimeImmutable('now'))->modify('+'.$seconds.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO mothership_upgrade_queue(player_id,mothership_id,module_key,level_before,level_after,starts_at,completes_at) VALUES(?,?,?,?,?,?,?)')->execute([$playerId,(int)$ship['id'],$module,$before,$before+1,$start,$complete]);$queueId=(int)$this->pdo->lastInsertId();if($cooldown>0){$next=(new DateTimeImmutable('now'))->modify('+'.$cooldown.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,'mothership_upgrade',$next]);}$this->event($playerId,(int)$ship['id'],'mothership_upgraded',['module'=>$module,'level_before'=>$before,'level_after'=>$before+1,'cost'=>$cost,'queue_id'=>$queueId,'queue_seconds'=>$seconds,'cooldown_seconds'=>$cooldown]);$this->pdo->commit();return ['state'=>'success','mothership_id'=>(int)$ship['id'],'module'=>$module,'level_before'=>$before,'level_after'=>$before+1,'cost'=>$cost,'queue_id'=>$queueId,'queue_seconds'=>$seconds,'cooldown_seconds'=>$cooldown];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
}
